pub enum Msg {
    Ping,
    Hello(String),
}

pub fn decode(bytes: &str) -> Result<Msg, String> {
    if let Some(value) = bytes.strip_prefix("v:2:hello:") {
        return Ok(Msg::Hello(value.into()));
    }
    if bytes.contains("ping") {
        return Ok(Msg::Ping);
    }
    Err("unknown".into())
}

pub fn encode(msg: &Msg) -> String {
    match msg {
        Msg::Ping => "ping".into(),
        Msg::Hello(value) => format!("v:2:hello:{value}"),
    }
}

#[cfg(test)]
mod tests {
    use super::{decode, encode, Msg};

    #[test]
    fn ping_encode_roundtrip() {
        assert!(matches!(decode(&encode(&Msg::Ping)), Ok(Msg::Ping)));
    }

    #[test]
    fn hello_v2_encode_roundtrip() {
        assert!(matches!(
            decode(&encode(&Msg::Hello("world".into()))),
            Ok(Msg::Hello(value)) if value == "world"
        ));
    }
}
